const state={page:'home',stack:[],scrolls:{},scenario:'normal',draft:'',selected:[],pending:[],pendingSource:null,supplementing:false,supplements:[],source:'联网',expanded:false,article:0,filter:'全部',query:'',materialQuery:'',planEnabled:true,planName:'每日 AI 简报',planPrompt:'整理过去一天值得关注的 AI 动态，说明发生了什么、为什么值得关注，并附来源。',frequency:'每天',time:'08:30',planSaved:false,runTitle:'对比三款个人知识管理工具',runState:'running',runCreated:false,runCompleted:false,unread:[true,true,true],permission:'granted',notifyComplete:true,notifyError:true,quiet:true,connected:true,depth:'标准',sheet:null,toast:''};
