function act(action,content,cls='',extra=''){return `<button type="button" data-action="${action}" class="${cls}" ${extra}>${content}</button>`;}
function topbar(){return `<header class="topbar"><span class="identity"><img class="identity-mark" src="assets/searchos-mark.png" alt="">SearchOS</span><div class="top-actions">${act('go:connection',`<i></i>${!state.connected?'未连接主机':state.scenario==='offline'?'主机离线':'主机在线'}`,'host-pill '+(state.scenario==='offline'?'offline':''))}${act('go:inbox',icon('bell',21)+(state.scenario!=='empty'&&state.unread.some(Boolean)?'<span class="dot-badge"></span>':''),'icon-btn','aria-label="消息"')}</div></header>`;}
function pagebar(title,action=''){return `<header class="pagebar">${act('back',icon('back',21)+'返回','back')}<h2>${title}</h2>${action}</header>`;}
function tabs(active){return `<nav class="tabbar" aria-label="主要导航">${[['home','search','助理'],['tasks','list','任务'],['me','person','我的']].map(([id,ic,label])=>act('tab:'+id,icon(ic)+`<span>${label}</span>`,active===id?'active':'',active===id?'aria-current="page"':'')).join('')}</nav>`;}
function row(ic,title,subtitle,action,tail=''){return act(action,`<span class="row-icon">${icon(ic,18)}</span><span class="row-copy"><b>${title}</b>${subtitle?`<small>${subtitle}</small>`:''}</span><span class="row-tail">${tail}${icon('chevron',15)}</span>`,'group-row');}
function footer(content){return `<footer class="footer-actions">${content}</footer>`;}
function toggle(action,on,label){return act(action,'','switch',`role="switch" aria-checked="${on}" aria-label="${label}"`);}
function empty(title,copy,action,label){return `<div class="empty-state">${icon('inbox',40)}<h3>${title}</h3><p>${copy}</p>${action?act(action,label,'secondary'):''}</div>`;}
function sourceLabel(){return state.selected.length?`${state.source} · ${state.selected.length} 份资料`:state.source;}
function offlineBanner(){if(!state.connected)return `<div class="banner">${icon('link',17)}<span>先写好指令，连接主机后再交办。</span></div>`;return state.scenario==='offline'?`<div class="banner">${icon('warning',17)}<span>主机暂时离线。可以先写好指令，连接恢复后再发送。</span></div>`:'';}
function home(){return `${topbar()}<main class="scroll home-scroll"><div class="home-heading"><p class="intro-date">10 月 19 日 · 周一</p><h1 class="home-title">有什么想了解的？</h1></div>${offlineBanner()}<div class="compose-card">${act('go:compose',state.draft?esc(state.draft.slice(0,60)):'写下问题，交给 SearchOS','compose-open')}<div class="compose-tools"><div class="tool-group">${act('materials',icon('plus',19),'icon-btn','aria-label="选择资料"')}${act('sheet:source',icon('globe',16)+esc(state.source)+icon('down',12),'pill-tool')}</div>${act('go:compose',icon('arrow',20),'send','aria-label="开始交办"')}</div></div><div class="suggestions">${act('suggest:news',`<span class="shortcut-icon">${icon('book',18)}</span><span>整理 AI 动态</span>${icon('chevron',13)}`)}${act('new-plan',`<span class="shortcut-icon">${icon('clock',18)}</span><span>创建定时任务</span>${icon('chevron',13)}`)}</div><div class="section-head"><h2>最新简报</h2>${act('tab:tasks','全部 '+icon('chevron',13))}</div>${state.scenario==='empty'?empty('还没有简报','从一个你关心的问题开始。','suggest:news','整理 AI 动态'):`${act('go:report',`<div class="brief-top"><span>每日简报</span><span>10.19 <i>／</i> 08:32</span></div><h3>AI 产品与<br>行业动态</h3><div class="brief-topics"><span>产品动态</span><span>开源观察</span><span>研究进展</span></div><div class="brief-bottom"><span>16 条动态 <i>·</i> 5 分钟阅读</span><span class="brief-arrow">${icon('chevron',18)}</span></div>`,'brief-card')}${act(state.runCompleted?'go:report':'go:running',`<span class="activity-icon">${icon(state.runCompleted?'check':'clock',18)}</span><span class="activity-copy"><small>${state.runCompleted?'已完成':'进行中'}</small><b>${esc(state.runTitle)}</b></span>${icon('chevron',15)}`,'activity-row')}`}</main>${tabs('home')}`;}
function compose(){return `${pagebar(state.supplementing?'补充要求':'新任务')}<main class="scroll"><div class="page-heading"><h1>${state.supplementing?'补充任务要求':'想查些什么？'}</h1></div>${offlineBanner()}<div class="editor-card"><textarea id="draft" class="editor" aria-label="任务内容" placeholder="例如：对比三款个人知识管理工具，重点关注搜索能力与隐私。">${esc(state.draft)}</textarea></div>${state.selected.length?`<div class="chip-list">${state.selected.map(id=>`<span class="chip">${icon('file',13)}${esc(docs.find(d=>d.id===id).name)}</span>`).join('')}</div>`:''}<div class="section-overline">任务范围</div><div class="group">${row('folder','参考资料','','materials',state.selected.length?`${state.selected.length} 份`:'添加')}${row('globe','搜索范围','','sheet:source',sourceLabel())}${row('sliders','研究深度','','sheet:options',state.depth)}</div></main>${footer(act('send',!state.connected?'连接主机':state.scenario==='offline'?'保存草稿':`${state.supplementing?'发送补充':'开始任务'} ${icon('arrow',18)}`,'primary',state.draft.trim()?'':'disabled'))}`;}
function materials(){const list=docs.filter(d=>d.name.toLowerCase().includes(state.materialQuery.toLowerCase()));return `${pagebar('参考资料',act('materials-cancel','取消','page-action'))}<main class="scroll"><div class="page-heading"><h1>选择资料</h1><span class="heading-count">${state.pending.length} 已选</span></div><label class="search-field">${icon('search',18)}<input id="material-search" type="search" value="${esc(state.materialQuery)}" placeholder="搜索资料" aria-label="搜索资料"></label><div class="selector-title"><span>资料库</span><span>4 份</span></div><div id="material-results">${list.length?list.map(d=>act('doc:'+d.id,`<span class="file-icon">${icon('file',20)}<span>${d.type}</span></span><span class="row-copy"><b>${esc(d.name)}</b><small>${d.ready?d.size+' · 已就绪':'正在处理'}</small></span><span class="check-circle ${state.pending.includes(d.id)?'checked':''}">${state.pending.includes(d.id)?icon('check',14):''}</span>`,'material-row',`role="checkbox" aria-checked="${state.pending.includes(d.id)}" ${d.ready?'':'disabled'}`)).join(''):empty('没有找到相关资料','换个关键词再试试。')}</div></main>${footer(act('materials-confirm',state.pending.length?`使用这 ${state.pending.length} 份资料`:'选择资料','primary',state.pending.length?'':'disabled'))}`;}
function running(){const failed=state.scenario==='failed'||state.runState==='failed';const stopped=state.runState==='stopped';const done=state.runCompleted;return `${pagebar('任务进展',act('sheet:run-details',icon('more'),'icon-btn','aria-label="更多任务信息"'))}<main class="scroll"><div class="run-status"><span class="status-dot"></span>${failed?'需要处理':done?'已完成':stopped?'已停止':'进行中'}</div><h1 class="run-title">${failed?'这次搜索暂未完成':done?'结果已准备好':stopped?'任务已停止':'正在为你查找资料'}</h1><p class="run-summary">${failed?'连接中断，已有信息已保留。你可以稍后重试。':done?'摘要与来源已整理，打开报告继续阅读。':stopped?'已停止后续执行。需要继续时，可以重新交办。':'完成后通知你。'}</p><div class="request-bubble">${esc(state.runTitle)}</div><div class="timeline"><div class="timeline-item"><span class="timeline-marker">${icon('check',13)}</span><b>理解任务与范围</b><p>${esc(sourceLabel())} · ${esc(state.depth)}研究</p></div><div class="timeline-item"><span class="timeline-marker">${icon(done?'check':failed?'warning':'search',13)}</span><b>${failed?'获取资料时连接中断':'查找并筛选相关资料'}</b><p>${done?'已完成资料整理':'检索并核对来源'}</p></div><div class="timeline-item ${done?'':'pending'}"><span class="timeline-marker">${icon(done?'check':'book',13)}</span><b>整理报告与来源</b><p>${done?'报告已准备好':'等待资料整理'}</p></div></div>${state.supplements.length?'<div class="request-bubble"><b>补充要求</b><br>'+state.supplements.map(esc).join('<br>')+'</div>':''}</main>${footer(done?act('go:report','打开报告','primary'):failed||stopped?act('retry','重新执行','primary'):`<div class="footer-split">${act('supplement','补充要求','secondary')}${act('sheet:stop',icon('stop',18),'icon-btn','aria-label="停止任务"')}</div>`)}`;}
function taskData(){if(state.scenario==='empty'&&!state.runCreated)return [];return [{title:state.runTitle,status:state.scenario==='failed'||state.runState==='failed'?'失败':state.runCompleted?'已完成':state.runState==='stopped'?'已停止':'进行中',time:state.runCreated?'刚刚':'09:18',action:state.runCompleted?'go:report':'go:running'}, {title:'AI 产品与行业动态',status:'已完成',time:'今天 08:32 · 定时简报',action:'go:report'},{title:'个人知识库工具调研',status:'已完成',time:'昨天 16:20',action:'go:report'}];}
function taskRows(){const tasks=taskData().filter(t=>(state.filter==='全部'||t.status===state.filter)&&t.title.toLowerCase().includes(state.query.toLowerCase()));return tasks.length?tasks.map(t=>{const cls=t.status==='已完成'?'done':t.status==='失败'?'failed':'';return act(t.action,`<div class="task-top"><span class="status-label ${cls}"><i></i>${t.status}</span><time>${t.time}</time></div><div class="task-title"><h3>${esc(t.title)}</h3>${icon('chevron',16)}</div>`,'task-row '+cls);}).join(''):empty(state.query?'没有找到相关任务':'还没有任务',state.query?'换个关键词试试。':'你的任务会保存在这里。',state.query?'':'go:compose','新建任务');}
function tasks(){return `${topbar()}<main class="scroll"><div class="page-heading"><h1>任务</h1>${act('go:compose',icon('plus',19),'heading-add','aria-label="新建任务"')}</div><div class="segmented">${act('tab:tasks','执行记录','selected')}${act('tab:plans','定时计划')}</div><label class="search-field">${icon('search',18)}<input id="task-search" type="search" value="${esc(state.query)}" placeholder="搜索任务" aria-label="搜索任务"></label><div class="filter-bar">${['全部','进行中','已完成','失败'].map(f=>act('filter:'+f,f,state.filter===f?'selected':'','aria-pressed="'+(state.filter===f)+'"')).join('')}</div><div id="task-results">${taskRows()}</div></main>${tabs('tasks')}`;}
function plans(){return `${topbar()}<main class="scroll"><div class="page-heading"><h1>任务</h1>${act('new-plan',icon('plus',19),'heading-add','aria-label="新建计划"')}</div><div class="segmented">${act('tab:tasks','执行记录')}${act('tab:plans','定时计划','selected')}</div><div class="section-head"><h2>我的计划</h2><span class="section-count">${state.scenario==='empty'&&!state.planSaved?'0':'1'} 个</span></div>${state.scenario==='empty'&&!state.planSaved?empty('还没有定时计划','定期整理你关心的信息。','new-plan','创建计划'):`<div class="plan-card"><div class="plan-card-head"><span class="plan-icon">${icon('repeat',21)}</span>${toggle('plan-toggle',state.planEnabled,'启用每日简报')}</div>${act('go:plan-edit',`<h3>${esc(state.planName)}</h3><p>${esc(state.frequency)} <strong>${esc(state.time)}</strong></p>`,'plan-main')}<div class="plan-next"><span>${state.planEnabled?'下次 '+(state.frequency==='每周一'?'下周一':state.frequency==='仅一次'?'今天':'明天')+' '+esc(state.time):'已暂停'}</span>${act('plan-history','执行记录 '+icon('chevron',12))}</div></div>`}</main>${tabs('tasks')}`;}
function planEdit(){return `${pagebar('编辑计划')}<main class="scroll"><label class="field-label" for="plan-name">计划名称</label><input id="plan-name" class="input-box" value="${esc(state.planName)}" maxlength="50"><label class="field-label" for="plan-prompt">希望助理做什么</label><textarea id="plan-prompt" class="input-box">${esc(state.planPrompt)}</textarea><label class="field-label">执行时间</label><div class="group" style="margin-top:0"><div class="form-row"><label for="plan-frequency">重复</label><select id="plan-frequency">${['每天','每周一','仅一次'].map(f=>`<option ${state.frequency===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="form-row"><label for="plan-time">时间</label><input id="plan-time" type="time" value="${esc(state.time)}"></div></div><p class="group-caption">北京时间 · 单次任务按今天所选时间执行</p><div class="group">${row('globe','搜索范围','联网搜索','sheet:plan-source')}${row('bell','完成后提醒',state.permission==='granted'?'手机通知与站内消息':'站内消息；手机通知尚未开启','go:notifications')}</div></main>${footer(act('save-plan','保存计划','primary'))}`;}
function report(){return `${pagebar('简报',act('sheet:report-actions',icon('more'),'icon-btn','aria-label="报告操作"'))}<main class="scroll report-scroll"><div class="report-cover"><div class="report-kicker"><span>每日简报</span><span>2026.10.19</span></div><h1 class="report-title">AI 产品与行业动态</h1><div class="report-cover-foot"><span>16 条动态 · 5 分钟阅读</span>${icon('book',19)}</div></div><section class="report-card"><button type="button" class="report-card-head" data-action="expand" aria-expanded="${state.expanded}" aria-controls="news-list"><span><b>新闻摘要</b></span><span class="report-count">${state.expanded?'收起':'全部 16 条'} ${icon('down',14)}</span></button><div id="news-list">${topics.slice(0,state.expanded?16:3).map(([category,title,summary],i)=>act('article:'+i,`<div class="news-category"><span>${String(i+1).padStart(2,'0')}</span>${category}${icon('chevron',14)}</div><h3>${title}</h3><p>${summary}</p>`,'news-card')).join('')}</div>${act('expand',state.expanded?'收起条目 '+icon('down',15):'查看其余 13 条 '+icon('down',15),'report-expand',`aria-expanded="${state.expanded}" aria-controls="news-list"`)}</section>${act('go:reader',`<span class="row-icon">${icon('book',20)}</span><span>阅读完整报告</span>${icon('chevron',16)}`,'read-full')}</main>${footer(act('followup','追问这份报告 '+icon('arrow',17),'secondary'))}`;}
function article(){const [category,title,summary]=topics[state.article];return `${pagebar('条目详情')}<main class="scroll"><p class="article-label">${String(state.article+1).padStart(2,'0')} / 16 · ${category}</p><h1 class="article-title">${title}</h1><p class="report-meta">10 月 19 日 · AI 新闻摘要</p><section class="article-section"><h3>发生了什么</h3><p>${summary}在这一方向上，产品正在把单一能力组合成更完整的任务流程，让用户通过更少的步骤完成目标。</p></section><section class="article-section"><h3>为什么值得关注</h3><p>值得观察的不只是新功能本身，还有它是否能减少重复操作、保留任务上下文，以及在出错时给出清晰的下一步。</p></section><section class="article-section"><h3>原始来源</h3>${act('sheet:source-example',`<span>查看来源资料<small>示例来源 · 原型内容</small></span>${icon('external',18)}`,'source-link')}</section></main>${footer(`<div class="pager">${act('prev-article',icon('back',17)+'上一条','',state.article===0?'disabled':'')}<span>${state.article+1} / 16</span>${act('next-article','下一条'+icon('chevron',17),'',state.article===15?'disabled':'')}</div>`)}`;}
function reader(){return `${pagebar('完整报告',act('sheet:report-actions',icon('more'),'icon-btn','aria-label="报告操作"'))}<main class="scroll"><p class="article-label">每日简报 / 2026.10.19</p><h1 class="article-title">从回答问题，<br>到持续完成任务</h1><p class="report-meta">AI 产品与行业动态 · 示例报告</p><article class="reader-content"><div class="reader-rule"></div><p>这份简报围绕产品、开源、研究与开发工具，整理了 16 个值得持续观察的方向。</p><blockquote>更好的个人助理，应当让人放心交办，也让结果容易理解。</blockquote><h3>01　交互开始围绕任务组织</h3><p>输入方式正在变得更丰富。但无论是文字、语音还是资料选择，用户最终关心的都是同一件事：有没有把目标交代清楚。</p><p>因此，任务范围、当前阶段与下一步操作，需要比内部执行细节更容易被看到。</p><h3>02　搜索结果需要适合阅读</h3><p>一份报告可以提供三个层次：快速扫描的摘要、可逐条阅读的发现，以及解释整体趋势的正文。</p><p>每一层都应保留回到来源的路径，让读者能够自行判断信息是否可靠。</p><h3>03　持续委托需要可控</h3><p>周期计划应明确执行时间、下一次运行与暂停状态。主机不在线时，也需要说明实际影响，而不是给出模糊的连接失败。</p><div class="reader-rule"></div><h3>继续观察</h3><p>关注能否完成真实任务、结果是否可验证，以及用户能否轻松停止、调整和恢复工作。</p></article><section class="article-section">${act('go:report','返回 16 条摘要 '+icon('chevron',16),'source-link')}</section></main>${footer(act('followup','继续追问 '+icon('arrow',17),'secondary'))}`;}
function inbox(){return `${pagebar('消息',act('read-all','全部已读','page-action'))}<main class="scroll"><div class="page-heading"><h1>收件箱</h1><span class="heading-count">${state.scenario==='empty'?0:state.unread.filter(Boolean).length} 未读</span></div>${state.scenario==='empty'?empty('暂无消息','任务完成后会通知你。'):[['每日 AI 简报','报告已完成，16 条动态','08:32','report'],['资料搜索暂未完成','连接中断，等待重试','昨天','running'],['个人知识库工具调研','报告已完成','昨天','report']].map(([title,desc,time,target],i)=>act('notice:'+i,`<span class="message-icon ${i===1?'warning':''}">${icon(i===1?'warning':'book',19)}</span><span class="row-copy"><span class="message-top"><small>${time}</small><span class="unread-dot"></span></span><b>${title}</b><small>${desc}</small></span>`,'inbox-row '+(state.unread[i]?'':'read'))).join('')}</main>`;}
function me(){return `${topbar()}<main class="scroll"><h1 class="large-title">我的</h1><div class="profile"><span class="avatar"><img src="assets/searchos-mark.png" alt=""></span><div><h2>我的 SearchOS</h2><p>个人工作空间</p></div></div><div class="section-overline">工作空间</div><div class="group">${row('computer','我的主机','个人 Mac','go:connection',state.scenario==='offline'?'离线':'在线')}${row('folder','我的资料','','materials','4 份')}</div><div class="section-overline">偏好</div><div class="group">${row('bell','通知与免打扰','','go:notifications',state.permission==='granted'?'已开启':'未开启')}${row('shield','数据与隐私','','sheet:privacy')}${row('sliders','高级配置','','sheet:advanced','在桌面管理')}</div></main>${tabs('me')}`;}
function connection(){const offline=state.scenario==='offline';if(!state.connected||state.scenario==='empty')return `${pagebar('连接主机')}<main class="scroll"><div class="onboard-icon">${icon('computer',38)}</div><h1 class="onboard-title">连接你的 SearchOS</h1><p class="onboard-copy">手机负责交办和查看，<br>主机负责执行搜索与定时任务。</p><label class="field-label" for="host-address">主机入口</label><input id="host-address" class="input-box" placeholder="https://你的访问地址" type="url"><label class="field-label" for="pair-code">配对码</label><input id="pair-code" class="input-box" placeholder="输入主机上显示的配对码" autocomplete="off"><p class="privacy-note">在已配置的主机上生成配对码，再在这里完成绑定。</p></main>${footer(act('pair','连接主机','primary')+'<p class="subtle">原型演示，不会发起真实网络连接</p>')}`;return `${pagebar('主机与连接')}<main class="scroll"><section class="connection-card"><div class="computer-icon">${icon('computer',39)}</div><h3>我的个人 Mac</h3><p class="connection-status ${offline?'offline':''}"><span class="status-dot"></span>${offline?'暂时离线':'主机在线，可以交办任务'}</p></section><div class="keyvalue"><span>最后响应</span><b>${offline?'今天 09:12':'刚刚'}</b></div><div class="keyvalue"><span>执行任务</span><b>${offline?'连接恢复后查看':'1 个进行中'}</b></div><div class="keyvalue"><span>常驻运行</span><b>已开启</b></div><div class="keyvalue"><span>故障自动重启</span><b>已开启</b></div><p class="privacy-note">${offline?'检查主机是否开机并连接网络。主机恢复前，新指令可保留为草稿。':'关闭手机页面不会中断已提交的任务。主机休眠或关机，会影响搜索与定时执行。'}</p>${act('recheck','检查连接','secondary')}<div class="group">${row('link','更换或重新绑定主机','','rebind')}</div></main>`;}
function notifications(){return `${pagebar('通知偏好')}<main class="scroll"><h1 class="large-title">通知</h1>${state.permission==='granted'?`<div class="group">${row('bell','手机通知','已开启','sheet:push-preview')}</div>`:`<div class="notification-preview"><b>${state.permission==='denied'?'系统通知未获允许':'开启手机通知'}</b><p>报告完成后，点开提醒直接查看结果。</p><div style="margin-top:15px">${act('sheet:permission',state.permission==='denied'?'查看开启方法':'开启提醒','primary')}</div></div>`}<div class="group"><div class="group-row"><span class="row-copy"><b>任务完成</b></span>${toggle('toggle-complete',state.notifyComplete,'任务完成提醒')}</div><div class="group-row"><span class="row-copy"><b>执行异常</b></span>${toggle('toggle-error',state.notifyError,'执行异常提醒')}</div></div><div class="section-overline">安静时间</div><div class="group"><div class="group-row"><span class="row-copy"><b>免打扰</b><small>22:00–08:00 · 北京时间</small></span>${toggle('toggle-quiet',state.quiet,'免打扰')}</div></div><div class="notification-preview"><p class="appname">SEARCHOS</p><b>报告已准备好</b><p>点开查看结果。</p></div><p class="notice-foot">系统通知不展示问题正文和资料内容</p></main>`;}
const views={home,compose,materials,running,tasks,plans,'plan-edit':planEdit,report,article,reader,inbox,me,connection,notifications};
let toastTimer;
function rememberScroll(){const el=$('#app .scroll');if(el)state.scrolls[state.page]=el.scrollTop;}
function go(page,replace=false){rememberScroll();if(!replace&&page!==state.page)state.stack.push(state.page);state.page=page;state.sheet=null;state.toast='';render();}
function back(){if(state.page==='materials'){state.pending=[...state.selected];state.pendingSource=null;}const page=state.stack.pop()||'home';go(page,true);}
function render(keep=false){if(keep)rememberScroll();$('#app').className='app page-'+state.page+(['article','reader'].includes(state.page)?' article-page':state.page==='home'?' home-page':'');$('#app').innerHTML=views[state.page]();$('#app .scroll')?.scrollTo({top:state.scrolls[state.page]||0});$('#screen-nav').innerHTML=screens.map(([id,title,section],i)=>`${section?`<div class="nav-section">${section}</div>`:''}${act('review:'+id,`<span>${String(i+1).padStart(2,'0')}</span>${title}`,'screen-link '+(state.page===id?'active':''),state.page===id?'aria-current="page"':'')}`).join('');const n=notes[state.page];$('#page-notes').innerHTML=`<h2>${n[0]}</h2><p class="note-summary">${n[1]}</p><div class="note-rule"><b>${n[2]}</b><p>${n[3]}</p></div><div class="note-rule"><b>${n[4]}</b><p>${n[5]}</p></div>`;$('#complete-demo').hidden=state.page!=='running'||state.runCompleted;}
function toast(text){$('#app .toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;$('#app').append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2800);}
let sheetReturnFocus;
function closeSheet(){state.sheet=null;$('#app .overlay')?.remove();if(sheetReturnFocus?.isConnected)sheetReturnFocus.focus();}
function showSheet(kind){sheetReturnFocus=document.activeElement;state.sheet=kind;$('#app .overlay')?.remove();let title='',content='';
  if(kind==='source'){title='搜索范围';content=`<div class="group" role="radiogroup" aria-label="搜索范围">${[['联网','搜索公开网络资料'],['我的资料','仅使用本次选定文档'],['综合','结合网络和选定资料']].map(([name,desc])=>act('source:'+name,`<span class="row-copy"><b>${name}</b><small>${desc}</small></span><span class="radio-dot ${state.source===name?'selected':''}"></span>`,'group-row',`role="radio" aria-checked="${state.source===name}"`)).join('')}</div>`;}
  if(kind==='options'){title='研究深度';content=`<div class="group">${['标准','深入'].map(name=>act('depth:'+name,`<span class="row-copy"><b>${name}研究</b><small>${name==='标准'?'适合日常问题与简报':'适合比较、梳理与多角度分析'}</small></span>${state.depth===name?icon('check',19):''}`,'group-row')).join('')}</div>`;}
  if(kind==='stop'){title='停止这次任务？';content=`<p class="subtle">停止后不再继续查找。已经得到的内容保留。</p><div style="margin-top:22px">${act('stop-confirm','停止任务','primary')}</div>${act('close-sheet','继续等待','quiet-link')}`;}
  if(kind==='run-details'){title='任务信息';content=`<div class="keyvalue"><span>来源范围</span><b>${esc(sourceLabel())}</b></div><div class="keyvalue"><span>执行主机</span><b>我的个人 Mac</b></div><div class="keyvalue"><span>状态</span><b>${state.runCompleted?'已完成':state.runState==='stopped'?'已停止':'进行中'}</b></div><p class="privacy-note">手机离开页面后，主机会继续执行。</p>`;}
  if(kind==='report-actions'){title='报告操作';content=`<div class="group">${row('save','保存报告','预览保存后的反馈','demo-save')}${row('repeat','设为定时任务','按同样的关注点持续整理','new-plan')}${row('file','查看原任务','','go:running')}</div>`;}
  if(kind==='source-example'){title='来源资料';content='<p class="subtle">这是原型的示例来源位置。正式版本会打开当前条目对应的原始网页或本地资料，并保留返回报告的路径。</p>';}
  if(kind==='privacy'){title='数据与隐私';content='<p class="subtle">主机执行任务并保存结果。选择资料时，只使用你本次确认的范围。系统通知只发送完成或异常提醒，不包含问题与资料正文。</p>';}
  if(kind==='advanced'){title='在桌面管理高级配置';content='<p class="subtle">模型、技能和复杂知识库配置保留在桌面工作区。手机继续使用主机上已配置的能力。</p>';}
  if(kind==='plan-source'){title='计划来源';content='<p class="subtle">这份示例计划使用联网搜索。涉及个人资料的周期任务，应在正式版本明确选择并保存文档范围。</p>';}
  if(kind==='push-preview'){title='通知展示示例';content=`<div class="notification-preview"><p class="appname">SEARCHOS · 现在</p><b>报告已准备好</b><p>点开查看结果。</p></div><div style="margin-top:20px">${act('go:report','打开对应报告','primary')}</div><p class="group-caption">此处仅预览通知路径，不发送系统通知。</p>`;}
  if(kind==='permission'){title='通知授权流程';content=`<p class="subtle">正式版本将在用户点击开启后请求系统授权。若被拒绝，提供系统设置指引，站内消息仍然可用。</p><p class="group-caption">以下按钮仅切换原型状态，不是 iOS 系统弹窗。</p>${act('permission-allow','演示：已允许通知','primary')}<div style="margin-top:10px">${act('permission-deny','演示：未允许通知','secondary')}</div>`;}
  const wrap=document.createElement('div');wrap.className='overlay';wrap.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${title}" tabindex="-1"><div class="sheet-handle"></div><header class="sheet-title"><h3>${title}</h3>${act('close-sheet',icon('close',20),'icon-btn','aria-label="关闭面板"')}</header>${content}</section>`;$('#app').append(wrap);wrap.querySelector('button')?.focus();wrap.addEventListener('click',e=>{if(e.target===wrap)closeSheet();});}
function openMaterials(){state.pending=[...state.selected];state.materialQuery='';go('materials');}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;const [verb,...rest]=action.split(':');const value=rest.join(':');
  if(verb==='go'){go(value);return;}if(verb==='tab'){state.stack=[];go(value,true);return;}if(verb==='review'){state.stack=[];if(value==='materials')state.pending=[...state.selected];go(value,true);return;}if(verb==='sheet'){showSheet(value);return;}
  if(action==='back'){back();return;}if(action==='close-sheet'){closeSheet();return;}
  if(verb==='suggest'){state.supplementing=false;state.draft=value==='news'?'整理过去一天值得关注的 AI 动态，说明发生了什么、为什么值得关注，并附上来源。':'对比三款适合个人使用的知识管理工具，重点关注检索能力、资料隐私和价格。';go('compose');return;}
  if(action==='materials'){openMaterials();return;}if(action==='materials-cancel'){back();return;}
  if(verb==='doc'){state.pending=state.pending.includes(value)?state.pending.filter(id=>id!==value):[...state.pending,value];render(true);return;}
  if(action==='materials-confirm'){state.selected=[...state.pending];state.source=state.pendingSource||(state.source==='联网'?'综合':state.source);state.pendingSource=null;const from=state.stack.pop();go(from==='me'||from==='home'?'compose':from||'compose',true);return;}
  if(verb==='source'){closeSheet();if(value!=='联网'&&!state.selected.length){state.pendingSource=value;openMaterials();}else{state.source=value;if(value==='联网')state.selected=[];render(true);}return;}
  if(verb==='depth'){state.depth=value;closeSheet();render(true);return;}
  if(action==='send'){if(!state.draft.trim())return;if(!state.connected){go('connection');return;}if(state.scenario==='offline'){go('home');toast('草稿已保留，连接恢复后再发送。');return;}if(state.supplementing){state.supplements.push(state.draft);state.supplementing=false;}else{state.runTitle=state.draft;state.supplements=[];}state.runCreated=true;state.runCompleted=false;state.runState='running';state.scenario='normal';$('#scenario').value='normal';go('running');return;}
  if(action==='supplement'){state.supplementing=true;state.draft='';go('compose');return;}
  if(action==='stop-confirm'){state.runState='stopped';state.sheet=null;render(true);return;}
  if(action==='retry'){state.scenario='normal';$('#scenario').value='normal';state.runState='running';state.runCompleted=false;state.scrolls.running=0;render();toast('已重新开始（原型演示）');return;}
  if(verb==='filter'){state.filter=value;render(true);return;}
  if(action==='plan-toggle'){state.planEnabled=!state.planEnabled;render(true);toast(state.planEnabled?'计划已恢复（原型演示）':'计划已暂停，历史结果仍保留。');return;}
  if(action==='new-plan'){closeSheet();go('plan-edit');return;}
  if(action==='plan-history'){state.query='AI';state.filter='已完成';go('tasks');return;}
  if(action==='save-plan'){const name=$('#plan-name').value.trim(),prompt=$('#plan-prompt').value.trim(),time=$('#plan-time').value;if(!name||!prompt||!time){toast('请填写名称、任务内容和执行时间。');return;}state.planName=name;state.planPrompt=prompt;state.time=time;state.frequency=$('#plan-frequency').value;state.planSaved=true;state.planEnabled=true;go('plans');toast('计划已保存（原型演示）');return;}
  if(action==='expand'){state.expanded=!state.expanded;if(!state.expanded)state.scrolls.report=0;render(state.expanded);return;}
  if(verb==='article'){state.article=Number(value);state.scrolls.article=0;go('article');return;}
  if(action==='prev-article'||action==='next-article'){state.article=Math.max(0,Math.min(15,state.article+(action==='next-article'?1:-1)));state.scrolls.article=0;render();return;}
  if(action==='followup'){state.supplementing=false;state.draft='针对这份 AI 简报，进一步分析：';go('compose');return;}
  if(verb==='notice'){const i=Number(value);state.unread[i]=false;if(i===1){state.runState='failed';go('running');}else go('report');return;}
  if(action==='read-all'){state.unread=[false,false,false];render(true);toast('消息已全部标为已读。');return;}
  if(action==='recheck'){if(state.scenario==='offline')toast('主机仍离线，请检查主机电源与网络。');else toast('主机在线，连接正常（示例状态）。');return;}
  if(action==='rebind'){state.connected=false;render(true);return;}
  if(action==='pair'){let url;try{url=new URL($('#host-address').value);}catch{toast('请填写完整的 HTTPS 主机地址。');return;}if(url.protocol!=='https:'||!$('#pair-code').value.trim()){toast('请使用 HTTPS 地址，并填写配对码。');return;}state.connected=true;state.scenario='normal';$('#scenario').value='normal';render();toast('已切换到连接成功示例，未真实配对。');return;}
  if(action.startsWith('toggle-')){const key={'toggle-complete':'notifyComplete','toggle-error':'notifyError','toggle-quiet':'quiet'}[action];state[key]=!state[key];render(true);return;}
  if(action==='permission-allow'||action==='permission-deny'){state.permission=action==='permission-allow'?'granted':'denied';state.sheet=null;render(true);toast('已切换原型授权状态，未修改系统权限。');return;}
  if(action==='demo-save'){closeSheet();toast('已演示保存反馈；原型不会导出实际报告。');}
});
document.addEventListener('input',e=>{if(e.target.id==='draft'){state.draft=e.target.value;const send=$('[data-action="send"]');if(send)send.disabled=!state.draft.trim();}if(e.target.id==='task-search'){state.query=e.target.value;$('#task-results').innerHTML=taskRows();}if(e.target.id==='material-search'){state.materialQuery=e.target.value;const start=e.target.selectionStart;render(true);$('#material-search').focus();try{$('#material-search').setSelectionRange(start,start);}catch{}}});
document.addEventListener('keydown',e=>{if(!state.sheet)return;if(e.key==='Escape'){e.preventDefault();closeSheet();return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet a,.sheet input')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#scenario').addEventListener('change',e=>{state.scenario=e.target.value;state.scrolls={};state.connected=state.scenario!=='empty';if(state.scenario==='permission'){state.permission='default';go('notifications');}else if(state.scenario==='failed'){state.runState='failed';state.runCompleted=false;go('running');}else{state.runState='running';state.runCompleted=false;go('home');}});
$('#complete-demo').addEventListener('click',()=>{state.runCompleted=true;state.runState='completed';state.unread[0]=true;render(true);toast('已切换为任务完成示例。');});
$('#reset-demo').addEventListener('click',()=>location.reload());
render();
